function friendReqNorm(t){return String(t||'').replace(/[\s，。！？、,.!?~～…]/g,'').toLowerCase();}
function friendReqUnique(c,text,attempt){const used=friendRequestUsedTexts(c),raw=friendReqText(text,'');if(raw&&!used.has(friendReqNorm(raw)))return raw;const n=Math.max(1,+attempt||1),pool=['先别把话彻底堵死，给我一次解释的机会。','我知道你还在生气，但我不想就这样结束。','这是我第'+n+'次来找你，我还是想把话说清楚。','不逼你原谅，只想让你听完我该说的话。','微信联系不上你，我只能再认真申请一次。','你可以继续拒绝，但我不能装作什么都没发生。'];return pool.find(x=>!used.has(friendReqNorm(x)))||('第'+n+'次申请，我还是想和你说清楚。');}
function friendReaddPrompt(c){if(!c)return'';const h=friendRejectHistory(c),o=c.friendOrigin||{},wasReadd=o.kind==='readd'||!!friendMetaGet(c,'readdedAt')||h.length;if(!wasReadd)return'';const rejected=h.length,requests=h.map(x=>'第'+x.attempt+'次「'+x.msg+'」').join('；')||('「'+(o.requestMsg||'想重新加回你')+'」');return '\n\n# 拉黑、重新申请与通过后的持续记忆（自然模式也必须保留）\n'+S.me.name+'之前在微信拉黑过你。你为恢复联系主动发过好友申请'+(rejected?'，其中被明确拒绝过 '+rejected+' 次':'')+'；申请内容包括：'+requests+'。后来是'+S.me.name+'重新通过了你的申请。你清楚自己为什么申请回来，也记得拉黑前的关系与矛盾；不能把因果说反成“只是因为对方加我”，不能装作这段经历不存在。被问“为什么还加回来/为什么申请/被拒了几次”时，要按人设和这些真实经历直接回答。';}
