function friendRequestsInit(){S.friendRequests=Array.isArray(S.friendRequests)?S.friendRequests.filter(Boolean):[];const now=Date.now(),expired=[];S.friendRequests.forEach(r=>{const c=getC(r.contactId);r.kind=r.kind||(c&&friendMainBlocked(c)?'readd':'created');r.status=['pending','accepted','rejected'].includes(r.status)?r.status:'pending';r.time=+r.time||now;r.visibleAt=+r.visibleAt||r.time;r.source=r.source||(r.kind==='readd'?'重新添加':'角色资料');r.intent=r.intent||(c&&c.friendOrigin&&c.friendOrigin.intent)||'';if(r.status==='rejected'&&now-(+r.decidedAt||r.time)>=86400000)expired.push(r.id);if(r.status==='accepted'&&(!c||c.deleted))expired.push(r.id);});if(expired.length){const ids=new Set(expired),contacts=new Set(S.friendRequests.filter(r=>ids.has(r.id)).map(r=>r.contactId));S.friendRequests=S.friendRequests.filter(r=>!ids.has(r.id));contacts.forEach(id=>{const c=getC(id);if(c&&c._friendPending&&!S.friendRequests.some(r=>r.contactId===id&&(r.status==='pending'||r.status==='accepted'))){Object.keys(S.messages||{}).forEach(k=>{if(k===id||k.indexOf(id+'#')===0)delete S.messages[k];});S.contacts=S.contacts.filter(x=>x!==c);}});save();}friendDiscoveryState();return S.friendRequests;}
